print(f"Total oral responses defined: {len(oral_responses)}")

# Read current src/data/oral.js
with open("src/data/oral.js", "r", encoding="utf-8") as f:
    text = f.read()

# Update each answer in src/data/oral.js
updated_count = 0
for qid, new_ans in oral_responses.items():
    escaped_id = re.escape(qid)
    # Find question object matching id
    pattern = r'(\{\s*id:\s*"' + escaped_id + r'",[\s\S]*?answer:\s*)"[\s\S]*?"(,\s*role:)'
    m = re.search(pattern, text)
    if m:
        json_ans = json.dumps(new_ans, ensure_ascii=False)
        replacement = m.group(1) + json_ans + m.group(2)
        text = text[:m.start()] + replacement + text[m.end():]
        updated_count += 1
    else:
        print(f"WARNING: Could not find question with id {qid}")

print(f"Updated {updated_count}/129 questions in memory.")

with open("src/data/oral.js", "w", encoding="utf-8") as f:
    f.write(text)

print("Saved updated src/data/oral.js successfully!")
